check.mjs.text:
#!/usr/bin/env node
// CLI: sends one real, unauthenticated, read-only GET request -- the
// anonymous listing endpoint -- to an AWS S3 bucket, a Google Cloud Storage
// bucket, or an Azure Blob container you name, and reports whether it
// allows public listing. Your machine, your network -- nothing goes
// through this portfolio.
//
//   node check.mjs <bucket-url> [--json] [--timeout <ms>]
//   node check.mjs --provider s3|gcs|azure --bucket <name> [--account <name>] [--json]
//
// <bucket-url> accepts the URL shape each provider's own docs describe:
//   S3    https://<bucket>.s3.amazonaws.com/   or  https://s3.amazonaws.com/<bucket>
//   GCS   https://storage.googleapis.com/<bucket>/  or  https://<bucket>.storage.googleapis.com/
//   Azure https://<account>.blob.core.windows.net/<container>
//
// Only point this at a bucket or container you own or are authorised to
// test. This sends one ordinary, unauthenticated GET -- the same request
// any anonymous visitor's browser could send -- and never fetches any
// individual object's content, only the listing.
//
// Exit code 0 when the bucket does not allow public listing (private, or
// does not exist); 1 when it does; 2 for a usage error, a request that could
// not complete (network error, timeout, bad name), or a response this tool
// could not classify (an "unknown" state -- never guessed at either way).

import { buildProbeUrl, detectTargetFromUrl, buildReport } from './engine.mjs';
import { runProbe } from './probe.mjs';

function formatText(report) {
  const lines = [];
  lines.push(`Target: ${report.target}`);
  lines.push(`Provider: ${report.provider ?? '(unknown)'}`);
  if (report.incomplete) {
    lines.push(`Request failed: ${report.error}`);
    lines.push('');
    lines.push('The probe did not complete -- re-run once the target is reachable.');
    return lines.join('\n');
  }
  lines.push(`Status: ${report.status}`);
  lines.push('');

  if (report.state === 'public-listing') {
    const f = report.findings[0];
    lines.push(`!! [DANGER] ${f.title}`);
    lines.push(`   ${f.detail}`);
    lines.push(
      `   ${f.objectCount}${f.truncated ? '+' : ''} object name(s) visible in this response` +
        (f.sampleKeys.length ? `, for example: ${f.sampleKeys.join(', ')}` : ''),
    );
  } else if (report.state === 'private') {
    lines.push('The bucket exists and denied the anonymous listing request. Not publicly listable.');
  } else if (report.state === 'not-found') {
    lines.push('No bucket/container by that name was found. Nothing to report.');
  } else {
    lines.push('The response did not match a recognised listing-or-error shape for this provider.');
    lines.push('This is inconclusive, not a clean result -- verify by hand before relying on it.');
  }

  lines.push('');
  lines.push(
    'This is evidence from one response, not a full security assessment -- see README.md for what ' +
      'this tool does and does not check.',
  );
  return lines.join('\n');
}

export function parseArgs(argv) {
  const args = { target: null, provider: null, bucket: null, account: null, json: false, timeoutMs: undefined };
  for (let i = 0; i < argv.length; i++) {
    const a = argv[i];
    if (a === '--json') args.json = true;
    else if (a === '--timeout') args.timeoutMs = Number(argv[++i]);
    else if (a === '--provider') args.provider = argv[++i];
    else if (a === '--bucket') args.bucket = argv[++i];
    else if (a === '--account') args.account = argv[++i];
    else if (!args.target && !a.startsWith('--')) args.target = a;
  }
  return args;
}

/** Pure orchestration: given a resolved target and a probe function
 * (real network, or a stub in tests), fetch and classify. Kept separate
 * from main() so tests can inject a fake `probeFn` instead of hitting the
 * network. */
export async function runCheck(resolved, { probeFn = runProbe, timeoutMs } = {}) {
  const probe = await probeFn(resolved, timeoutMs ? { timeoutMs } : {});
  return buildReport(resolved.probeUrl, probe);
}

export function resolveFromArgs(args) {
  if (args.provider || args.bucket || args.account) {
    if (!args.provider || !args.bucket) {
      return { ok: false, error: '--provider and --bucket must both be given when using the explicit form' };
    }
    return buildProbeUrl({ provider: args.provider, bucket: args.bucket, account: args.account });
  }
  if (!args.target) {
    return { ok: false, error: 'usage-error' };
  }
  return detectTargetFromUrl(args.target);
}

async function main() {
  const args = parseArgs(process.argv.slice(2));
  const resolved = resolveFromArgs(args);

  if (!resolved.ok) {
    if (resolved.error === 'usage-error') {
      console.error('Usage: node check.mjs <bucket-url> [--json] [--timeout <ms>]');
      console.error('   or: node check.mjs --provider s3|gcs|azure --bucket <name> [--account <name>]');
    } else {
      console.error(resolved.error);
    }
    process.exit(2);
  }

  const report = await runCheck(resolved, { timeoutMs: args.timeoutMs });

  if (args.json) {
    console.log(JSON.stringify(report, null, 2));
  } else {
    console.log(formatText(report));
  }
  process.exit(report.incomplete || report.state === 'unknown' ? 2 : report.ok ? 0 : 1);
}

if (import.meta.url === `file://${process.argv[1]}`) {
  main();
}

engine.mjs.text:
// Pure logic for the cloud bucket exposure check: no network, no I/O. Two
// jobs live here, kept separate from the network layer (probe.mjs) the same
// way git-exposure-check and subdomain-takeover-check split theirs, so the
// CLI (which fetches for real) and the browser page (which can only ever
// analyse a payload someone already fetched) import exactly one
// classification engine each.
//
//   1. `resolveTarget` -- turn a bucket URL or a provider+bucket pair into
//      the one HTTP GET this tool ever sends: the bucket's own anonymous
//      LIST-contents endpoint, in each provider's own documented form.
//   2. `buildReport` -- classify the response into a verdict, reading the
//      response BODY (a provider's own listing-or-error XML), not just the
//      status code -- the same reason git-exposure-check reads a body
//      instead of trusting a bare 200/403/404.
//
// Three providers, one shared XML shape for two of them. AWS S3's classic
// listing API and Google Cloud Storage's XML API are both S3-compatible:
// a public bucket answers with a `<ListBucketResult>` root element holding
// one `<Contents><Key>...</Key></Contents>` per object; a private or
// missing bucket answers with an `<Error><Code>...</Code></Error>` naming
// AccessDenied or NoSuchBucket. Azure Blob Storage's container-listing API
// is its own schema (`<EnumerationResults>` / `<Blobs><Blob><Name>`), but
// the same three-way shape -- public listing, denied, not found -- applies.
//
// What this deliberately never does: fetch any individual object's content.
// The one request this tool sends is a LIST, never a GET on a listed key --
// finding out a bucket is publicly listable is the exposure; downloading
// what is inside it is a different, higher-liability action a real
// penetration test would take with authorisation, the same restraint
// git-exposure-check documents for not requesting `.git/index` or a packed
// object once HEAD/config already confirm exposure.

/** The three providers this tool understands. */
export const PROVIDERS = ['s3', 'gcs', 'azure'];

// A bucket/container name valid under AWS's and GCS's shared naming rules:
// 3-63 chars, lowercase letters, digits, dots and hyphens, must start and
// end with a letter or digit. Loose on purpose -- this only has to reject
// something that obviously is not a bucket name (a stray "/" or space),
// not fully validate one; an over-strict check would reject a real bucket
// this tool has never seen a name shape for.
const BUCKET_NAME_RE = /^[a-z0-9][a-z0-9.-]{1,61}[a-z0-9]$/i;
// Azure storage account names: 3-24 chars, lowercase letters and digits only.
const AZURE_ACCOUNT_RE = /^[a-z0-9]{3,24}$/i;
// Azure containers follow the same rule as S3/GCS buckets minus dots.
const AZURE_CONTAINER_RE = /^[a-z0-9][a-z0-9-]{1,61}[a-z0-9]$/i;

/**
 * Build the one URL this tool ever requests -- a provider's anonymous
 * bucket-listing endpoint -- from an explicit provider + bucket (+ account
 * for Azure).
 *
 * @returns {{ok: true, provider: string, bucket: string, account: string|null,
 *   probeUrl: string} | {ok: false, error: string}}
 */
export function buildProbeUrl({ provider, bucket, account } = {}) {
  if (!PROVIDERS.includes(provider)) {
    return { ok: false, error: `unknown provider "${provider}" -- expected one of ${PROVIDERS.join(', ')}` };
  }
  if (typeof bucket !== 'string' || !bucket) {
    return { ok: false, error: 'a bucket (or container) name is required' };
  }

  if (provider === 's3') {
    if (!BUCKET_NAME_RE.test(bucket)) return { ok: false, error: `"${bucket}" is not a plausible S3 bucket name` };
    // Path-style, not virtual-hosted: works for every bucket name (a name
    // containing a dot breaks the virtual-hosted TLS certificate match) and
    // needs no region guess -- AWS's path-style endpoint 307-redirects to
    // the bucket's real region, which the probe layer follows.
    return { ok: true, provider, bucket, account: null, probeUrl: `https://s3.amazonaws.com/${encodeURIComponent(bucket)}` };
  }

  if (provider === 'gcs') {
    if (!BUCKET_NAME_RE.test(bucket)) return { ok: false, error: `"${bucket}" is not a plausible GCS bucket name` };
    return { ok: true, provider, bucket, account: null, probeUrl: `https://storage.googleapis.com/${encodeURIComponent(bucket)}` };
  }

  // azure
  if (!account || !AZURE_ACCOUNT_RE.test(account)) {
    return { ok: false, error: 'azure needs a storage account name (3-24 lowercase letters/digits) via --account' };
  }
  if (!AZURE_CONTAINER_RE.test(bucket)) {
    return { ok: false, error: `"${bucket}" is not a plausible Azure container name` };
  }
  return {
    ok: true,
    provider,
    bucket,
    account,
    probeUrl: `https://${account}.blob.core.windows.net/${encodeURIComponent(bucket)}?restype=container&comp=list`,
  };
}

// Recognises the bucket-root URL shapes each provider's own docs describe,
// so a caller can paste a URL they already have instead of splitting it
// into provider/bucket/account by hand.
const S3_VIRTUAL_HOSTED_RE = /^([a-z0-9][a-z0-9.-]{1,61}[a-z0-9])\.s3[.-]([a-z0-9-]+\.)?amazonaws\.com$/i;
const S3_PATH_STYLE_RE = /^s3[.-]([a-z0-9-]+\.)?amazonaws\.com$/i;
const GCS_VIRTUAL_HOSTED_RE = /^([a-z0-9][a-z0-9.-]{1,61}[a-z0-9])\.storage\.googleapis\.com$/i;
const GCS_PATH_STYLE_HOST = 'storage.googleapis.com';
const AZURE_HOST_RE = /^([a-z0-9]{3,24})\.blob\.core\.windows\.net$/i;

/**
 * Parse a bucket-root URL the caller already has into the same shape
 * `buildProbeUrl` returns, detecting the provider from the hostname.
 *
 * @returns {{ok: true, provider, bucket, account, probeUrl} | {ok: false, error}}
 */
export function detectTargetFromUrl(input) {
  let url;
  try {
    url = new URL(input);
  } catch (err) {
    return { ok: false, error: `not a valid URL: ${err.message}` };
  }
  if (url.protocol !== 'https:' && url.protocol !== 'http:') {
    return { ok: false, error: `unsupported scheme: ${url.protocol}` };
  }
  const host = url.hostname;

  let m = S3_VIRTUAL_HOSTED_RE.exec(host);
  if (m) return buildProbeUrl({ provider: 's3', bucket: m[1] });

  if (S3_PATH_STYLE_RE.test(host)) {
    const bucket = url.pathname.replace(/^\/+/, '').split('/')[0];
    if (!bucket) return { ok: false, error: 'path-style S3 URL is missing the bucket name in its path' };
    return buildProbeUrl({ provider: 's3', bucket });
  }

  m = GCS_VIRTUAL_HOSTED_RE.exec(host);
  if (m) return buildProbeUrl({ provider: 'gcs', bucket: m[1] });

  if (host.toLowerCase() === GCS_PATH_STYLE_HOST) {
    const bucket = url.pathname.replace(/^\/+/, '').split('/')[0];
    if (!bucket) return { ok: false, error: 'GCS URL is missing the bucket name in its path' };
    return buildProbeUrl({ provider: 'gcs', bucket });
  }

  m = AZURE_HOST_RE.exec(host);
  if (m) {
    const container = url.pathname.replace(/^\/+/, '').split('/')[0];
    if (!container) return { ok: false, error: 'Azure blob URL is missing the container name in its path' };
    return buildProbeUrl({ provider: 'azure', bucket: container, account: m[1] });
  }

  return {
    ok: false,
    error:
      `unrecognised host "${host}" -- expected an S3 bucket (*.s3.amazonaws.com or s3.amazonaws.com/<bucket>), ` +
      'a GCS bucket (storage.googleapis.com/<bucket> or *.storage.googleapis.com), or an Azure container ' +
      '(*.blob.core.windows.net/<container>)',
  };
}

// -- Response classification -------------------------------------------

const LIST_BUCKET_RESULT_RE = /<ListBucketResult[\s>]/i;
const ENUMERATION_RESULTS_RE = /<EnumerationResults[\s>]/i;
const ERROR_CODE_RE = /<Code>([^<]+)<\/Code>/i;
const KEY_RE = /<Key>([^<]*)<\/Key>/g;
const IS_TRUNCATED_RE = /<IsTruncated>\s*(true|false)\s*<\/IsTruncated>/i;
// Each <Blob> entry's own first child is always <Name> in Azure's schema;
// the lazy [\s\S]*? stops at the first match after each <Blob> opening tag.
const AZURE_BLOB_NAME_RE = /<Blob>[\s\S]*?<Name>([^<]*)<\/Name>/g;
const AZURE_NEXT_MARKER_RE = /<NextMarker>\s*([^<\s][^<]*)?<\/NextMarker>/i;

// Error codes that mean "this bucket/container exists and refused an
// anonymous listing" -- the good outcome.
const DENIED_CODES = new Set([
  'AccessDenied',
  'PublicAccessNotPermitted',
  'AuthorizationPermissionMismatch',
  'AuthenticationFailed',
  'InvalidAccessKeyId',
]);
// Error codes that mean "no such bucket/container" -- not a security
// finding, just a name that does not resolve to anything.
const NOT_FOUND_CODES = new Set(['NoSuchBucket', 'BucketNotFound', 'ContainerNotFound', 'ResourceNotFound']);

const MAX_SAMPLE_KEYS = 5;

function decodeXmlEntities(s) {
  return String(s)
    .replace(/&amp;/g, '&')
    .replace(/&lt;/g, '<')
    .replace(/&gt;/g, '>')
    .replace(/&quot;/g, '"')
    .replace(/&apos;/g, "'");
}

function extractKeys(bodySample, re) {
  const keys = [];
  re.lastIndex = 0;
  let m;
  while ((m = re.exec(bodySample)) !== null && keys.length < MAX_SAMPLE_KEYS) {
    keys.push(decodeXmlEntities(m[1]));
  }
  return keys;
}

function countMatches(bodySample, re) {
  re.lastIndex = 0;
  let n = 0;
  while (re.exec(bodySample) !== null) n++;
  return n;
}

/**
 * Classify one probe response into a verdict. Pure and deterministic --
 * matches a response body against each provider's own documented XML
 * shape, the same "read the body, not just the status" approach
 * git-exposure-check uses for a soft-404-proof result.
 *
 * @param {string} target - display label (the URL that was probed)
 * @param {{status: number|null, bodySample: string, provider: string,
 *   truncated?: boolean, error: string|null}} probe
 * @returns {{target, provider, status, findings: object[], dangerCount,
 *   ok: boolean, incomplete: boolean, state: string}}
 */
export function buildReport(target, probe) {
  const p = probe && typeof probe === 'object' ? probe : {};
  const provider = p.provider ?? null;
  const status = typeof p.status === 'number' ? p.status : null;
  const body = typeof p.bodySample === 'string' ? p.bodySample : '';
  const incomplete = p.ok === false || status === null;

  if (incomplete) {
    return {
      target,
      provider,
      status,
      findings: [],
      dangerCount: 0,
      ok: false,
      incomplete: true,
      state: 'error',
      error: p.error ?? 'no response',
    };
  }

  const isS3Style = provider === 's3' || provider === 'gcs';
  const looksPublicS3 = isS3Style && LIST_BUCKET_RESULT_RE.test(body);
  const looksPublicAzure = provider === 'azure' && ENUMERATION_RESULTS_RE.test(body);
  const errorMatch = ERROR_CODE_RE.exec(body);
  const errorCode = errorMatch ? errorMatch[1] : null;

  const findings = [];
  let state = 'unknown';

  if (looksPublicS3 || looksPublicAzure) {
    const sampleKeys = looksPublicS3 ? extractKeys(body, KEY_RE) : extractKeys(body, AZURE_BLOB_NAME_RE);
    const objectCount = looksPublicS3 ? countMatches(body, KEY_RE) : countMatches(body, AZURE_BLOB_NAME_RE);
    const truncated = looksPublicS3
      ? /true/i.test(IS_TRUNCATED_RE.exec(body)?.[1] ?? '')
      : AZURE_NEXT_MARKER_RE.test(body);
    state = 'public-listing';
    findings.push({
      id: 'bucket-publicly-listable',
      severity: 'danger',
      title: `This ${provider === 'azure' ? 'container' : 'bucket'} allows anonymous public listing`,
      detail:
        `The response is a real, well-formed ${provider === 'azure' ? 'Azure container-listing (EnumerationResults)' : provider === 'gcs' ? 'GCS bucket-listing (ListBucketResult)' : 'S3 bucket-listing (ListBucketResult)'} ` +
        `document, not an access-denied error -- anyone on the internet can enumerate its contents with no ` +
        `credentials. Object names alone are already often sensitive (customer IDs, internal filenames, backup ` +
        `dates); if the bucket is ALSO configured for public object read, every listed name is directly ` +
        `downloadable. This tool did not fetch any object's content -- only the listing -- so it cannot say ` +
        `whether public-read is also enabled; verify that separately in the provider's own console before ` +
        `assuming otherwise.`,
      objectCount,
      sampleKeys,
      truncated,
    });
  } else if (errorCode && DENIED_CODES.has(errorCode)) {
    state = 'private';
  } else if (errorCode && NOT_FOUND_CODES.has(errorCode)) {
    state = 'not-found';
  } else if (status === 404) {
    state = 'not-found';
  } else if (status === 403) {
    // A 403 with no parseable <Code> is still a denial -- treat the same as
    // a matched DENIED_CODES entry rather than falling through to "unknown".
    state = 'private';
  } else {
    state = 'unknown';
  }

  const dangerCount = findings.filter((f) => f.severity === 'danger').length;

  return {
    target,
    provider,
    status,
    findings,
    dangerCount,
    ok: dangerCount === 0 && state !== 'unknown',
    incomplete: false,
    state,
    error: null,
  };
}

probe.mjs.text:
// Sends the one real HTTP request this check depends on: a GET to a cloud
// provider's own anonymous bucket-listing endpoint, built by engine.mjs.
// Node's built-in http/https clients are used directly (the same choice
// git-exposure-check makes) so the body read can be capped -- a bucket that
// really is publicly listable can report thousands of objects, and this
// tool only needs enough of the body to classify the result and show a
// handful of example names, not the whole listing.
//
// Unlike git-exposure-check's probe, this one DOES follow redirects, up to
// a small cap. That is not a relaxation of the "only look at what the
// target actually serves" rule -- it is required for AWS's own path-style
// endpoint to work at all: `s3.amazonaws.com/<bucket>` 307-redirects to the
// bucket's real region (`s3.<region>.amazonaws.com/<bucket>`) whenever the
// caller does not already know the region, which is the ordinary case here
// since this tool never asks the visitor for one. Every redirect is
// followed as a fresh GET to the `Location` the SAME provider's own server
// returned -- never to an arbitrary third party -- and the cap (5) exists
// only to bound a misbehaving or looping server, not because a real S3
// lookup needs more than one hop in practice.
//
// This module only ever talks to the one bucket-listing URL it is given
// (and the redirects that URL's own response names). It makes no other
// network call, reads no local files, and sends nothing anywhere else.

import { request as httpRequest } from 'node:http';
import { request as httpsRequest } from 'node:https';

const DEFAULT_TIMEOUT_MS = 10_000;
const BODY_CAP_BYTES = 16_384;
const MAX_REDIRECTS = 5;
const USER_AGENT =
  'cloud-bucket-exposure-check/1 (+https://duncan-haywood.github.io/monorepo-projects/cloud-bucket-exposure-check/)';

/**
 * One GET request to `targetUrl`, following same-request-method redirects
 * up to `MAX_REDIRECTS` times. Resolves rather than rejects on any failure
 * so a caller never needs a try/catch around it.
 *
 * @returns {Promise<{ok: boolean, status: number|null, url: string|null,
 *   bodySample: string, truncated: boolean, error: string|null}>}
 */
export function sendProbe(targetUrl, { timeoutMs = DEFAULT_TIMEOUT_MS } = {}) {
  return new Promise((resolve) => {
    let hops = 0;

    const attempt = (urlString) => {
      let parsed;
      try {
        parsed = new URL(urlString);
      } catch (err) {
        resolve({ ok: false, status: null, url: null, bodySample: '', truncated: false, error: `invalid URL: ${err.message}` });
        return;
      }
      if (parsed.protocol !== 'http:' && parsed.protocol !== 'https:') {
        resolve({ ok: false, status: null, url: parsed.href, bodySample: '', truncated: false, error: `unsupported scheme: ${parsed.protocol}` });
        return;
      }

      const requester = parsed.protocol === 'https:' ? httpsRequest : httpRequest;
      const headers = { 'user-agent': USER_AGENT, accept: '*/*' };

      let settled = false;
      const finish = (result) => {
        if (settled) return;
        settled = true;
        resolve(result);
      };

      const req = requester(parsed, { method: 'GET', headers, timeout: timeoutMs }, (res) => {
        const status = res.statusCode ?? null;

        if (status !== null && status >= 300 && status < 400 && res.headers.location) {
          res.resume(); // discard the redirect response body
          if (hops >= MAX_REDIRECTS) {
            finish({ ok: false, status, url: parsed.href, bodySample: '', truncated: false, error: 'too many redirects' });
            return;
          }
          hops += 1;
          const next = new URL(res.headers.location, parsed).href;
          attempt(next);
          return;
        }

        let bytes = Buffer.alloc(0);
        let truncated = false;
        res.on('data', (chunk) => {
          if (bytes.length >= BODY_CAP_BYTES) {
            truncated = true;
            return;
          }
          bytes = Buffer.concat([bytes, chunk]).subarray(0, BODY_CAP_BYTES);
          if (bytes.length >= BODY_CAP_BYTES) {
            truncated = true;
            res.destroy(); // stop reading once the cap is reached
          }
        });
        const complete = () =>
          finish({ ok: true, status, url: parsed.href, bodySample: bytes.toString('utf8'), truncated, error: null });
        res.on('end', complete);
        // `res.destroy()` above (hitting the cap) fires 'close' instead of
        // 'end' -- still a completed, successful read of everything up to
        // the cap.
        res.on('close', complete);
        res.on('error', (err) => finish({ ok: false, status, url: parsed.href, bodySample: '', truncated: false, error: err.message }));
      });
      req.on('timeout', () => req.destroy(new Error('timed out')));
      req.on('error', (err) => finish({ ok: false, status: null, url: parsed.href, bodySample: '', truncated: false, error: err.message }));
      req.end();
    };

    attempt(targetUrl);
  });
}

/** Runs the probe against a resolved target (the shape `buildProbeUrl` /
 * `detectTargetFromUrl` in engine.mjs return) and folds the provider back
 * into the result, since `buildReport` needs it to pick the right XML
 * shape to look for. */
export async function runProbe(resolved, opts = {}) {
  const result = await sendProbe(resolved.probeUrl, opts);
  return { ...result, provider: resolved.provider };
}

usage.mjs.text:
// Records an anonymous, aggregate-only local usage count: the event name and
// the current day, kept in the visitor's own browser. It never stores the
// bucket name, provider, target URL, or the pasted probe JSON -- that is
// exactly the kind of thing that must not be transmitted anywhere, and this
// tool never reads it off the visitor's machine either.

const STORAGE_KEY = 'cloud-bucket-exposure-check-usage';

function honorsBrowserSignal() {
  try {
    return globalThis.navigator?.doNotTrack === '1' || globalThis.navigator?.globalPrivacyControl === true;
  } catch {
    return false;
  }
}

export function recordUsage(storage = globalThis.localStorage, optedOut = false, event = 'check_run') {
  if (optedOut || !storage || readOptOut(storage) || honorsBrowserSignal()) return;
  try {
    const today = new Date().toISOString().slice(0, 10);
    const current = JSON.parse(storage.getItem(STORAGE_KEY) || '{}');
    current[event] = (current[event] || 0) + 1;
    current.last_day = today;
    storage.setItem(STORAGE_KEY, JSON.stringify(current));
  } catch {
    // A browser refusing site data must not stop the page computing a result.
  }
}

// The opt-out choice is kept in its own key, not in the counters:
// opting out *removes* the counters, so a flag stored inside them would
// be deleted by the very act it records. `recordUsage` above consults it
// directly as well as taking the caller's argument -- a stored preference
// that only one line of page wiring reads is one line away from being
// forgotten.
export function readOptOut(storage = globalThis.localStorage) {
  try {
    return storage?.getItem(`${STORAGE_KEY}-opt-out`) === '1';
  } catch {
    // A blocked or full store must never be read as consent.
    return false;
  }
}

export function writeOptOut(storage = globalThis.localStorage, optedOut = false) {
  if (!storage) return;
  // Independent writes, counters first: sharing one try means a setItem
  // that throws on a full quota skips the delete entirely, and the
  // visitor gets neither half of what the control promised.
  if (optedOut) {
    try { storage.removeItem(STORAGE_KEY); } catch { /* storage is optional */ }
    try { storage.setItem(`${STORAGE_KEY}-opt-out`, '1'); } catch { /* storage is optional */ }
  } else {
    try { storage.removeItem(`${STORAGE_KEY}-opt-out`); } catch { /* storage is optional */ }
  }
}
